    for r in range(n):
        for c in range(n):
            d = abs(c-center)
            if (r+d) % 2 == 0 and d <= r and r <= (n-1):
                # outer widening boundary is color 2 through row n//2
                if r <= n//2 and (d == r or (r == 0 and d == 0)):
                    out[r][c] = 2
                elif r >= n//2 and (r-d) % 4 == 0:
                    out[r][c] = 1
                elif r < n//2 and (r-d) % 2 == 0:
                    out[r][c] = 2
    # The observed construction is an expanding diamond weave; use diagonal patterns.
    for r in range(n):
        for c in range(n):
            x=abs(c-center)
            if r < n//2:
                if x<=r and (r-x)%2==0:
                    out[r][c]=2
            else:
                if x<=n-1-r and (r+x)%2==1:
                    out[r][c]=1
    return out
